GREEN_CCIP_POOL_ID: constant(uint256) = 24
VAULT_MIGRATOR_ID: constant(uint256) = 25
RIPE_RESERVE_ENGINE_ID: constant(uint256) = 26
RIPE_RESERVE_VESTING_ID: constant(uint256) = 27


@deploy
